// ── COLOUR GRADING helpers (sRGB ↔ Lab) — used by paint() and the colour QA; no need to edit ──
function _lin(v) { return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }
function _srgb(v) { return v <= 0.0031308 ? 12.92 * v : 1.055 * Math.pow(v, 1 / 2.4) - 0.055; }
function _f(t) { return t > 0.008856 ? Math.cbrt(t) : 7.787 * t + 16 / 116; }
function _fi(t) { const t3 = t * t * t; return t3 > 0.008856 ? t3 : (t - 16 / 116) / 7.787; }
function hexToLab(h) {
  const [r, g, b] = [1, 3, 5].map(i => _lin(parseInt(h.slice(i, i + 2), 16) / 255));
  const X = (r * 0.4124 + g * 0.3576 + b * 0.1805) / 0.95047, Y = r * 0.2126 + g * 0.7152 + b * 0.0722, Z = (r * 0.0193 + g * 0.1192 + b * 0.9505) / 1.08883;
  const fx = _f(X), fy = _f(Y), fz = _f(Z);
  return [116 * fy - 16, 500 * (fx - fy), 200 * (fy - fz)];
}
function labToHex([L, a, b]) {
  const fy = (L + 16) / 116, fx = fy + a / 500, fz = fy - b / 200;
  const X = 0.95047 * _fi(fx), Y = _fi(fy), Z = 1.08883 * _fi(fz);
  const rl = X * 3.2406 - Y * 1.5372 - Z * 0.4986, gl = -X * 0.9689 + Y * 1.8758 + Z * 0.0415, bl = X * 0.0557 - Y * 0.2040 + Z * 1.0570;
  return "#" + [rl, gl, bl].map(v => Math.round(Math.max(0, Math.min(1, _srgb(Math.max(0, v)))) * 255).toString(16).padStart(2, "0")).join("").toUpperCase();
}
function gradeHex(hex, g) {
  const [L, a, b] = hexToLab(hex);
  let L2 = g.dL == null ? L : L + g.dL, a2 = a * g.k + g.da, b2 = b * g.k + g.db;
  if (g.dL == null && g.pre === "night-dimmed") L2 = Math.min(40, Math.max(34, L * 0.42 + 8)); // night furniture stays a little lighter than the night wall
  if (g.dL == null && g.pre === "frost-dimmed") L2 = L * 0.72;
  const C = Math.hypot(a2, b2);
  if (C < 2.5) { const h = C > 0.5 ? Math.atan2(b2, a2) : Math.atan2(g.db || -1, g.da || 0); a2 = 5.5 * Math.cos(h); b2 = 5.5 * Math.sin(h); } // never let a calm tint collapse to grey
  return labToHex([L2, a2, b2]);
}
// framePalette(b): the six colours [name, hex] this frame's setting is painted in — location tint × mood.
// Revision 12: calm chapter tints are softened toward white — a faint hint of the chapter's colour, never a pastel wash.
function softHex(hex, k) {
  const [L, a, b] = hexToLab(hex);
  const wallish = !["floor", "ground"].includes(k);
  const L2 = wallish ? L + (96.5 - L) * 0.5 : L + (91 - L) * 0.35;
  const f = wallish ? 0.5 : 0.65; let a2 = a * f, b2 = b * f;
  const C = Math.hypot(a2, b2); if (C < 4 && C > 0.3) { a2 *= 4 / C; b2 *= 4 / C; } // keep a visible hint — never a dead grey
  return labToHex([L2, a2, b2]);
}
function framePalette(b) {
  const M = MOOD[b.mood];
  if (!M) throw new Error(`Unknown MOOD "${b.mood}" in ${b.ref}`);
  const pal = { wall: M.wall, floor: M.floor, furn: M.furn, sky: M.sky, ground: M.ground, field: M.field };
  if (M.kind === "white") { const C0 = CHAPTER[String(b.sequence).slice(0, 2)]; if (b.mood === "ACCENT") { const SW0 = WORLD[b.world] && WORLD[b.world].set && SET[WORLD[b.world].set]; const w = SW0 ? SW0.wall : (C0 ? C0.calm.wall : M.wall); return { ...pal, wall: w, field: w }; } return { ...pal, furn: C0 ? C0.calm.furn : M.furn }; } // v17: ACCENT = one soft wall colour, everything else white // Revision 12: white space
  if (b.mood === "DARK" || b.mood === "ICY") return pal; // night and memories keep one code across the film
  const C = CHAPTER[String(b.sequence).slice(0, 2)];
  if (!C) return pal;
  if (M.kind === "calm") { // Revision 10: the chapter's own palette, graded gently by the calm mood
    const g = GRADE[b.mood];
    const tint = x => [`${g.pre} ${x[0]}`, gradeHex(x[1], g)];
    const W = WORLD[b.world], S = W && W.set && SET[W.set];
    if (S) return { wall: tint(S.wall), floor: tint(S.floor), furn: S.furn, sky: tint(C.calm.sky), ground: tint(S.ground), field: tint(S.wall) }; // Revision 13: every real place keeps its own colours (place bible)
    const out = {}; for (const k of ["wall", "floor", "sky", "ground", "field"]) out[k] = tint(C.calm[k]); out.furn = C.calm.furn;
    return out;
  }
  return C.emo ? { ...C.emo } : pal; // the chapter's one emotional tone
}

