  "GATE": { name: "THE SAFETY GATE", hex: "#00A6A0", colour: "teal", danger: false, nouns: ["gate"], text: "THE SAFETY GATE: one low wooden pressure gate as wide as a doorway and about as tall as DAUGHTER's shoulders, in flat teal (#00A6A0): a row of round-topped upright spindles between one sturdy top rail and one bottom rail, and one chunky lever latch on its right side that snaps down to lock." },
  "BOOK": { name: "THE PARENTING BOOK", hex: "#7B4FD6", colour: "violet", danger: false, nouns: ["book","books"], text: "THE PARENTING BOOK: one thick hardback about the size of MOM's head in violet (#7B4FD6), with a rounded spine crossed by two raised bands, one round white badge of two linked rings on the cover, a red ribbon bookmark hanging out at the bottom and slightly dog-eared pages." },
  "BOOK_TOWER": { name: "THE TOWER OF PARENTING BOOKS", hex: "#7B4FD6", colour: "violet", danger: false, nouns: ["books"], text: "THE TOWER OF PARENTING BOOKS: exactly five thick hardback books stacked flat into one slightly leaning tower taller than MOM, each with a flat violet (#7B4FD6) cover, a thick white block of page edges, one slim pale yellow (#F1E08A) bookmark strip sticking out of its side at a different height, and no writing anywhere — five closed outlines, five flat violet fills, five white page edges, five bookmarks, nothing else." },
