  "CEREAL_RINGS": { name: "THE SCATTERED OAT RINGS", hex: "#D9A55B", colour: "warm tan", danger: false, nouns: ["Cheerios"], text: "THE SCATTERED OAT RINGS: exactly twelve small round oat rings, each smaller than a mitten hand, in flat warm tan (#D9A55B) with one black outline and one small hole in the middle, spread apart through the air or across the floor, none touching another." },
