  "ICE_CREAM": { name: "THE ICE CREAM", hex: "#E5457F", colour: "raspberry", danger: false, nouns: ["ice cream"], text: "THE ICE CREAM: one small ice-cream cone about the size of a mitten hand: one pointed cone in warm tan (#D9A55B) with three thin criss-cross lines and one round scoop of raspberry (#E5457F) ice cream on top — two closed outlines, two flat fills, then the three lines, nothing else." },
  "CANDY": { name: "THE CANDY BAR", hex: "#E5457F", colour: "raspberry", danger: false, nouns: ["candy", "sweets"], text: "THE CANDY BAR: one small flat rectangular candy bar about the size of a mitten hand, in a raspberry (#E5457F) wrapper with one plain white stripe across it and no letters — one closed outline, one flat raspberry fill, then the white stripe, nothing else." },
  "CHECKLIST": { name: "THE CHECKLIST", hex: "#E8A317", colour: "gold", danger: false, nouns: ["checklist","list"], text: "THE CHECKLIST: one white (#FFFFFF) sticker chart on paper, stuck flat on the fridge door by one small round magnet on its top edge, with exactly three round sticker circles in a column down its left side, each followed by one short grey line, with no letters; an earned circle holds one gold (#E8A317) five-pointed star sticker with a black outline, an unearned circle stays empty." },
  "WHITE_FLAG": { name: "THE WHITE FLAG", hex: "#FFFFFF", colour: "white", danger: false, nouns: ["flag", "surrender"], text: "THE WHITE FLAG: one small white (#FFFFFF) rectangular flag with one black outline, fixed to one thin straight stick in warm brown (#8B6A4E) — nothing else." },
  "RAIN_CLOUD": { name: "THE RAIN CLOUD", hex: "#8A96A6", colour: "slate grey", danger: false, nouns: ["cloud"], text: "THE RAIN CLOUD: one small flat rounded cloud about the size of MOM's head, in slate grey (#8A96A6) with one black outline, three round puffs along its top, a small sulky face — two black dot eyes and one short downturned mouth line — and exactly five short straight rain dashes falling from its underside; it floats in the air touching nothing unless the action says a character holds, catches or pushes it." },
  "PARK_CLOCK": { name: "THE PARK CLOCK", hex: "#F2A900", colour: "amber", danger: false, nouns: ["clock"], text: "THE PARK CLOCK: one round clock face on top of one slim straight post, standing about twice as tall as MOM, the post and the thick round rim in flat amber (#F2A900), the face plain white with two black hands and no numbers — one closed outline, the amber and white fills, then the two hands, nothing else." },
  "SIGNPOST": { name: "THE SIGNPOST", hex: "#00A6A0", colour: "teal", danger: false, nouns: ["option", "sign"], text: "THE SIGNPOST: one plain wooden post in warm brown (#8B6A4E) about as tall as MOM, carrying exactly three arrow-shaped boards with no writing: the left board in dusty orange (#C99A76) pointing left, the right board in dusty blue (#9DB0C4) pointing right, and the top board in bright teal (#00A6A0) pointing straight ahead — nothing else." },
