  "TEDDY": { name: "THE TEDDY BEAR", hex: "#F2A900", colour: "amber", danger: false, nouns: ["teddy"], text: "THE TEDDY BEAR: one small soft teddy bear about the size of ANNA's head, in flat amber (#F2A900), with two round ears — the left ear sewn back on with four short black cross-stitches — two black dot eyes, one small black oval nose, two short arms and two short legs — one closed outline, one flat amber fill, then those details, nothing else." },
  "PENDULUM_CLOCK": { name: "THE PENDULUM CLOCK", hex: "#A0522D", colour: "sienna brown", danger: false, nouns: ["clock"], text: "THE PENDULUM CLOCK: one tall standing pendulum clock a little taller than GRANDPA, in flat sienna brown (#A0522D): one tall narrow case, one round white face at the top with two black hands and no numbers, and one round brass-coloured (#C9A15A) pendulum disc on a straight rod visible through one tall window in the case — one closed outline, one flat sienna fill, then the face, hands and pendulum, nothing else." },
  "MIRROR": { name: "THE HALL MIRROR", hex: "#C9D6E3", colour: "pale grey-blue", danger: false, nouns: ["mirror"], text: "THE HALL MIRROR: one oval wall mirror about twice the size of MOM's head, hanging on the wall above the hall table, with one plain thin frame in muted wood brown (#9B7B5B) and a flat pale grey-blue (#C9D6E3) glass surface with no reflections except what the action names." },
  // ── metaphor objects ──
  "PLANE": { name: "THE PLANE", hex: "#FFC928", colour: "sunflower yellow", danger: false, nouns: ["plane"], text: "THE PLANE: one small passenger plane seen side-on: one rounded white (#FFFFFF) body with one broad flat sunflower yellow (#FFC928) stripe along its length, one swept wing, one upright tail fin in sunflower yellow and exactly five small round windows in a row — one closed outline, the white and sunflower fills, then the wing, fin and five windows, nothing else." },
