  "GAUGE": { name: "THE PRESSURE GAUGE", hex: "#D32F2F", colour: "danger red", danger: true, nouns: ["gauge", "pressure"], text: "THE PRESSURE GAUGE: one round pressure gauge about the size of MOM's head, with a plain white (#FFFFFF) face, a thick black outline, one black needle pivoting from a small black centre dot, and one thick arc of danger red (#D32F2F) along the upper right of the face, no numbers — nothing else." },
  "CAR": { name: "THE LITTLE CAR", hex: "#F07A10", colour: "orange", danger: false, nouns: ["car"], text: "THE LITTLE CAR: one small rounded car seen from slightly above and to the side, in flat orange (#F07A10), with two side windows in pale grey (#E6E6E6) and four round black wheels — one closed outline, one flat orange fill, then the two windows and four wheels, nothing else." },
  "BALANCE_SCALE": { name: "THE BALANCE SCALE", hex: "#B59A5E", colour: "muted brass", danger: false, nouns: ["balance","scale"], text: "THE BALANCE SCALE: one tall old-fashioned balance scale in muted brass (#B59A5E): one straight upright post on one flat round base, topped by one small round brass bird with one black dot eye perched on the post, one straight crossbar resting on top of the post under the bird, and two shallow round pans hanging from its two ends on three straight lines each — nothing else." },
  "HEART_CUSHION": { name: "THE HEART CUSHION", hex: "#E5457F", colour: "raspberry", danger: false, nouns: ["kindness","warmth"], text: "THE HEART CUSHION: one soft plump heart-shaped cushion about the size of MOM's head in raspberry (#E5457F), with one raised piped seam running round its whole edge and one small square cream (#F1E9D6) patch sewn near its point with four short cross-stitches." },
  "TEST_SHEET": { name: "THE TEST SHEET", hex: "#FFFFFF", colour: "white", danger: false, nouns: ["test"], text: "THE TEST SHEET: one large white (#FFFFFF) sheet of paper lying flat, with exactly four rows of three small empty square boxes down its left side and no letters or numbers anywhere — one closed outline, one flat white fill, then the twelve boxes, nothing else." },
  "RED_PEN": { name: "THE RED PEN", hex: "#D32F2F", colour: "danger red", danger: true, nouns: ["pen"], text: "THE RED PEN: one thin marker pen about twice the length of a mitten hand, in flat danger red (#D32F2F), with one rounded cap end and one pointed tip — one closed outline, one flat red fill, nothing else." },
  // ── Revision 1: giant objects and bolder metaphors (each is a known object grown, so it stays recognisable) ──
